/** Cities grouped by country code (drives the dependent country → city select). */
export const CITIES_BY_COUNTRY: Record<string, GeoCity[]> = CITIES.reduce(
  (acc, city) => {
    (acc[city.code] ??= []).push(city);
    return acc;
  },
  {} as Record<string, GeoCity[]>,
);

/** Nearest city to given coordinates (used for the optional GPS autofill). */
export function nearestCity(lat: number, lng: number): GeoCity | null {
  let best: GeoCity | null = null;
  let bestDist = Infinity;
  for (const c of CITIES) {
    const dLat = (c.lat - lat) * 111.32;
    const dLng = (c.lng - lng) * 111.32 * Math.cos((lat * Math.PI) / 180);
    const d = Math.sqrt(dLat * dLat + dLng * dLng);
    if (d < bestDist) {
      bestDist = d;
      best = c;
    }
  }
  return bestDist <= 350 ? best : null;
}

/** Flag emoji from an ISO 3166-1 alpha-2 code (no asset downloads needed). */
export function flagEmoji(code: string): string {
  if (!/^[A-Za-z]{2}$/.test(code)) return "";
  return String.fromCodePoint(...[...code.toUpperCase()].map((ch) => 0x1f1e6 + ch.charCodeAt(0) - 65));
}
